package pt.qpetiscos.agenda;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.widget.*;import android.view.*;import org.json.*;import java.net.*;import java.io.*;
public class MainActivity extends Activity {
 static final String SITE="https://joaopereira1995.github.io/agenda-qpetiscos/";
 WebView web; FrameLayout root; ImageView splash;
 @Override public void onCreate(Bundle b){super.onCreate(b);root=new FrameLayout(this);web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));splash=new ImageView(this);splash.setBackgroundColor(-1);splash.setImageResource(R.drawable.splash_logo);splash.setScaleType(ImageView.ScaleType.CENTER_INSIDE);root.addView(splash,new FrameLayout.LayoutParams(-1,-1));setContentView(root);
 web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);android.webkit.CookieManager.getInstance().setAcceptCookie(true);
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if("https".equals(u.getScheme())&&"joaopereira1995.github.io".equals(u.getHost())&&u.getPath()!=null&&u.getPath().startsWith("/agenda-qpetiscos/"))return false;if("https".equals(u.getScheme()))startActivity(new Intent(Intent.ACTION_VIEW,u));return true;}@Override public void onPageFinished(WebView v,String u){splash.setVisibility(View.GONE);} });web.loadUrl(SITE);new Handler(Looper.getMainLooper()).postDelayed(()->splash.setVisibility(View.GONE),6000);checkUpdate(); }
 void checkUpdate(){new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL("https://api.github.com/repos/joaopereira1995/agenda-qpetiscos/releases/latest").openConnection();c.setConnectTimeout(8000);c.setReadTimeout(8000);c.setRequestProperty("Accept","application/vnd.github+json");if(c.getResponseCode()!=200){c.disconnect();return;}ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}c.disconnect();JSONObject j=new JSONObject(out.toString("UTF-8"));String tag=j.getString("tag_name");if(!newer(tag,BuildConfig.VERSION_NAME))return;JSONArray assets=j.getJSONArray("assets");for(int i=0;i<assets.length();i++){JSONObject x=assets.getJSONObject(i);if(!x.getString("name").endsWith(".apk"))continue;String url=x.getString("browser_download_url");if(!url.startsWith("https://github.com/joaopereira1995/agenda-qpetiscos/releases/download/"))continue;runOnUiThread(()->{if(!isFinishing())new AlertDialog.Builder(this).setTitle("Atualização disponível").setMessage("Nova versão: "+tag).setNegativeButton("Mais tarde",null).setPositiveButton("Descarregar",(d,w)->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)))).show();});break;}}catch(Exception ignored){} }).start();}
 static boolean newer(String a,String b){String[] x=a.replaceFirst("^v","").split("\\."),y=b.split("\\.");for(int i=0;i<Math.max(x.length,y.length);i++){int n=i<x.length?Integer.parseInt(x[i]):0,m=i<y.length?Integer.parseInt(y[i]):0;if(n!=m)return n>m;}return false;}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}